const fs = require('fs');
const data = fs.readFileSync(0);
let idx = 0;

function nextInt() {
  while (idx < data.length && data[idx] <= 32) idx++;
  let n = 0;
  while (idx < data.length && data[idx] > 32) {
    n = n * 10 + (data[idx] - 48);
    idx++;
  }
  return n;
}

const N = nextInt();
const M = nextInt();

const adj1 = Array.from({ length: N + 1 }, () => []);
for (let i = 0; i < N - 1; i++) {
  const a = nextInt();
  const b = nextInt();
  adj1[a].push(b);
  adj1[b].push(a);
}

const adj2 = Array.from({ length: M + 1 }, () => []);
for (let i = 0; i < M - 1; i++) {
  const a = nextInt();
  const b = nextInt();
  adj2[a].push(b);
  adj2[b].push(a);
}

function bfs(start, adj, n, needParent) {
  const dist = new Int32Array(n + 1).fill(-1);
  const parent = needParent ? new Int32Array(n + 1).fill(-1) : null;
  const q = new Int32Array(n);

  let head = 0;
  let tail = 0;
  let far = start;
  let maxd = 0;

  dist[start] = 0;
  q[tail++] = start;

  while (head < tail) {
    const v = q[head++];
    const dv = dist[v];

    if (dv > maxd) {
      maxd = dv;
      far = v;
    }

    const list = adj[v];
    for (let i = 0; i < list.length; i++) {
      const to = list[i];
      if (dist[to] === -1) {
        dist[to] = dv + 1;
        if (parent) parent[to] = v;
        q[tail++] = to;
      }
    }
  }

  return { far, parent };
}

function getCenter(n, adj) {
  const a = bfs(1, adj, n, false).far;
  const res = bfs(a, adj, n, true);
  const b = res.far;

  const path = [];
  let cur = b;
  while (cur !== -1) {
    path.push(cur);
    cur = res.parent[cur];
  }

  return path[Math.floor(path.length / 2)];
}

const c1 = getCenter(N, adj1);
const c2 = getCenter(M, adj2);

process.stdout.write(c1 + ' ' + c2 + '\n');
